// fn-id-call trace (ADR-0060 §1). Logged on purpose: only the api name, the HTTP status and a reason code.
export const code = async (inputs) => {
  const apis = ['profile-get', 'profile-upsert', 'profile-batch', 'consent-set', 'account-delete'];
  const api = apis.includes(inputs.api) ? inputs.api : 'other';
  const status = Number.isInteger(inputs.status) ? inputs.status : 0;
  const reason = typeof inputs.reason === 'string' && /^[a-z0-9_]{1,20}$/.test(inputs.reason) ? inputs.reason : 'other';
  return { api, status, reason };
};

// fn-id-call result (ADR-0060 §1, §6). logInput/logOutput OFF: the ID answer carries personal data.
export const code = async (inputs) => {
  const isObj = (v) => v !== null && typeof v === 'object' && !Array.isArray(v);
  const down = (reason) => ({ ok: false, status: 0, body: {}, reason });
  const signReason = typeof inputs.sign_reason === 'string' ? inputs.sign_reason : '';
  if (signReason !== 'ok') return down(/^[a-z_]{1,20}$/.test(signReason) ? signReason : 'not_configured');
  const out = inputs.out;
  if (!isObj(out)) return down('network');
  // 2xx: {status, headers, body}; 4xx/5xx/timeout: {response: {status, body?}}.
  const r = out.status === undefined && isObj(out.response) ? out.response : out;
  const status = Number.isInteger(r.status) && r.status >= 100 && r.status <= 599 ? r.status : 0;
  if (!status) return down('network');
  if (!isObj(r.body)) return down('no_json');
  const ok = status >= 200 && status < 300 && r.body.ok === true;
  return { ok, status, body: r.body, reason: ok ? 'ok' : 'http_' + status };
};

// fn-id-call sign (ADR-0060 §1, ID ADR-0012). logInput/logOutput OFF: the key, the body, the signature.
export const code = async (inputs) => {
  const crypto = require('node:crypto');
  const fail = (reason) => ({ reason, url: '', envelope: {} });
  const urls = {
    'profile-get': inputs.url_profile_get,
    'profile-upsert': inputs.url_profile_upsert,
    'profile-batch': inputs.url_profile_batch,
    'consent-set': inputs.url_consent_set,
    'account-delete': inputs.url_account_delete,
  };
  const api = typeof inputs.api === 'string' ? inputs.api : '';
  if (!Object.prototype.hasOwnProperty.call(urls, api)) return fail('bad_api');
  const key = inputs.key;
  if (typeof key !== 'string' || key.length < 32 || key.includes('{{')) return fail('not_configured');
  const url = typeof urls[api] === 'string' ? urls[api] : '';
  if (!/^https:\/\/app\.flow\.aiqadam\.org\/api\/v1\/webhooks\/[A-Za-z0-9]{1,40}\/sync$/.test(url)) return fail('not_configured');
  const body = inputs.body;
  if (body === null || typeof body !== 'object' || Array.isArray(body)) return fail('bad_body');
  const canon = (v) => {
    if (v === null || v === undefined) return 'null';
    if (typeof v !== 'object') return JSON.stringify(v);
    if (Array.isArray(v)) return '[' + v.map(canon).join(',') + ']';
    return '{' + Object.keys(v).sort().map((k) => JSON.stringify(k) + ':' + canon(v[k])).join(',') + '}';
  };
  const ts = String(Math.floor((Number.isFinite(inputs.now_ms) ? inputs.now_ms : Date.now()) / 1000));
  const request_id = 'ev-' + crypto.randomBytes(16).toString('hex');
  const bodyHash = crypto.createHash('sha256').update(canon(body), 'utf8').digest('hex');
  const signature = crypto.createHmac('sha256', key).update('events\n' + ts + '\n' + request_id + '\n' + bodyHash, 'utf8').digest('hex');
  return { reason: 'ok', url, envelope: { module: 'events', ts, request_id, signature, body } };
};
